const map = { BOOKING_CREATED: 'заброньовано', BOOKING_RESCHEDULED: 'перенесено', BOOKING_CANCELLED: 'скасовано' };
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || {};
  const p = b.payload || {};
  const a = (p.attendees || [])[0] || {};
  // ignore PING and any other events, and payloads without an attendee e-mail
  if (!map[b.triggerEvent] || !a.email) continue;
  out.push({ json: {
    email: a.email,
    name: a.name || '',
    booking_start: p.startTime || null,
    booking_status: map[b.triggerEvent],
    booking_meet_url: (p.metadata && p.metadata.videoCallUrl) || (p.videoCallData && p.videoCallData.url) || p.location || '',
    booking_uid: p.uid || '',
  } });
}
return out;
